package com.dukankhata.supplier;
import com.dukankhata.common.exception.*; import com.dukankhata.common.security.CurrentUserService; import com.dukankhata.supplier.dto.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.util.*;
@Service public class SupplierService{
 private final SupplierRepository suppliers; private final SupplierLedgerRepository ledger; private final CurrentUserService current; private final com.dukankhata.notification.automation.AutomatedNotificationService automatedNotifications;
 public SupplierService(SupplierRepository suppliers,SupplierLedgerRepository ledger,CurrentUserService current,com.dukankhata.notification.automation.AutomatedNotificationService automatedNotifications){this.suppliers=suppliers;this.ledger=ledger;this.current=current;this.automatedNotifications=automatedNotifications;}
 @Transactional(readOnly=true) public List<SupplierResponse> list(){return suppliers.findAllByShopIdAndActiveTrueOrderByNameAsc(current.shopId()).stream().map(SupplierResponse::from).toList();}
 @Transactional public SupplierResponse create(SupplierRequest r){String name=r.name().trim(); if(suppliers.existsByShopIdAndNameIgnoreCaseAndActiveTrue(current.shopId(),name)) throw new ConflictException("A supplier with this name already exists"); Supplier s=new Supplier();s.setShop(current.requireUser().getShop());s.setName(name);s.setMobile(trim(r.mobile()));s.setAddress(trim(r.address()));return SupplierResponse.from(suppliers.save(s));}
 @Transactional public SupplierResponse update(UUID id,SupplierRequest r){Supplier s=locked(id);String name=r.name().trim();if(!name.equalsIgnoreCase(s.getName())&&suppliers.existsByShopIdAndNameIgnoreCaseAndActiveTrue(current.shopId(),name))throw new ConflictException("A supplier with this name already exists");s.setName(name);s.setMobile(trim(r.mobile()));s.setAddress(trim(r.address()));return SupplierResponse.from(suppliers.save(s));}
 @Transactional public void deactivate(UUID id){Supplier s=locked(id);if(s.getBalancePayable().signum()!=0)throw new BusinessException("Cannot deactivate a supplier with an outstanding payable balance");s.setActive(false);suppliers.save(s);}
 @Transactional public SupplierResponse pay(UUID id,SupplierPaymentRequest r){Supplier s=locked(id);BigDecimal a=money(r.amount());if(s.getBalancePayable().compareTo(a)<0)throw new BusinessException("Payment cannot exceed supplier payable balance");s.setBalancePayable(s.getBalancePayable().subtract(a));suppliers.save(s);entry(s,SupplierLedgerType.PAYMENT,a,r.reference());return SupplierResponse.from(s);}
 @Transactional(readOnly=true) public SupplierResponse get(UUID id){return SupplierResponse.from(suppliers.findByIdAndShopIdAndActiveTrue(id,current.shopId()).orElseThrow(()->new ResourceNotFoundException("Supplier not found")));}
 @Transactional(readOnly=true) public List<SupplierLedgerResponse> ledger(UUID id){suppliers.findByIdAndShopIdAndActiveTrue(id,current.shopId()).orElseThrow(()->new ResourceNotFoundException("Supplier not found"));return this.ledger.findTop100BySupplierIdAndShopIdOrderByCreatedAtDesc(id,current.shopId()).stream().map(SupplierLedgerResponse::from).toList();}
 @Transactional public void charge(Supplier s,BigDecimal amount,String ref){Supplier locked=locked(s.getId());BigDecimal a=money(amount);locked.setBalancePayable(locked.getBalancePayable().add(a));suppliers.save(locked);entry(locked,SupplierLedgerType.CHARGE,a,ref);}
 private void entry(Supplier s,SupplierLedgerType type,BigDecimal amount,String ref){SupplierLedgerEntry e=new SupplierLedgerEntry();e.setShop(s.getShop());e.setSupplier(s);e.setType(type);e.setAmount(amount);e.setBalanceAfter(s.getBalancePayable());e.setReference(trim(ref));ledger.save(e);}
 private Supplier locked(UUID id){return suppliers.findByIdAndShopIdForUpdate(id,current.shopId()).orElseThrow(()->new ResourceNotFoundException("Supplier not found"));}
 private BigDecimal money(BigDecimal x){if(x==null||x.signum()<=0)throw new BusinessException("Amount must be greater than zero");return x.setScale(2,RoundingMode.HALF_UP);}
 private String trim(String x){return x==null||x.isBlank()?null:x.trim();}
}
